
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ludena_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ludena", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.439417119089030e+01, 2.434649686400661e+01, 2.427631606941563e+01, 2.417289541882846e+01, 2.402101583916856e+01, 2.380004617695145e+01, 2.348158434233218e+01, 2.301031177187468e+01, 2.217316980362211e+01, 1.984015203456965e+01, 1.155060761453061e+01, 1.086681597934295e+00, 3.092139408199985e-01, 5.907593863065859e-01, 7.441752130840367e-01, 7.547201795734184e-01, 7.069619977210215e-01, 6.482679336939907e-01, 6.034971624558374e-01, 5.743491734340817e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


